function NewYearFundUtils.GetActivityData()
    local ActivityMgr = import('Game.Activity.ActivityMgr')
    local ActivityConstants = import("Game.Activity.ActivityConstants")

    local t = ActivityMgr:GetInstance():GetActivityData()
    if not t then
        return nil
    end
    for k, v in pairs(t) do
        if checkInt(v.type) == ActivityConstants.ActivityType.NewYearFund then
            return v
        end
    end

    return nil
end

function NewYearFundUtils.IsDrawRewardById(id)
    local newYearFundComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NewYearFundComponent)
    local t = newYearFundComponent:GetRewards()

    for k, v in pairs(t) do
        if checkNumber(v) == checkNumber(id) then
            return true
        end
    end
    return false
end

function NewYearFundUtils.IsCanDrawBaseRewardById(id)
    local newYearFundComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NewYearFundComponent)
    local num = newYearFundComponent:GetSignDay()

    local vo = NewYearFundUtils.GetNewYearFundRewardVo(id)
    return checkNumber(num) >= checkNumber(vo.taskNum)
end

function NewYearFundUtils.IsCanDrawPayRewardById(id)
    local newYearFundComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NewYearFundComponent)
    local num = newYearFundComponent:GetSignDay()

    local vo = NewYearFundUtils.GetNewYearFundPayRewardVo(id)
    return checkNumber(num) >= checkNumber(vo.taskNum)
end

--是否领取了这一天的
function NewYearFundUtils.IsCanDrawRewardBuyDay(id, num)
    local newYearFundComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NewYearFundComponent)
    local signDay = newYearFundComponent:GetSignDay()
    if checkNumber(signDay) < checkNumber(num) then
        return false, "", localize("未达到天数")
    end

    local baseId = CfUtils.GetStringIdGroupData(string.format("%s".."TypeDayMap", AutoIds.IdSetting6711), id.."_"..num)
    local payId = CfUtils.GetStringIdGroupData(string.format("%s".."TypeDayMap", AutoIds.IdSetting6712), id.."_"..num)

    local isDrawBase = NewYearFundUtils.IsDrawRewardById(baseId)
    local isDrawPay = NewYearFundUtils.IsDrawRewardById(payId)

    local isPay = newYearFundComponent:GetIsPay()
    if isPay then
        if isDrawBase and isDrawPay then
            return false, "", localize("该奖励已领取")
        end
    else
        if isDrawBase then
            return false, "", localize("该奖励已领取")
        end
    end

    local isCanDrawBase =NewYearFundUtils.IsCanDrawBaseRewardById(baseId)
    local isCanDrawPay = NewYearFundUtils.IsCanDrawPayRewardById(payId)
    if isPay then
        if not isCanDrawBase and not isCanDrawBase then
            return false, "", localize("未达到天数")
        end
    else
        if not isCanDrawBase then
            return false, "", localize("未达到天数")
        end
    end

    local ids = ""
    if isPay then
        if not isDrawBase and isCanDrawBase then
            ids = baseId
        end
        if not isDrawPay and isCanDrawPay then
            if ids == "" then
                ids = payId
            else
                ids = ids..","..payId
            end
        end
    else
        ids = baseId
    end

    return true, ids, ""
end

--是否有可以领取的奖励
function NewYearFundUtils.IsHaveCanDrawReward(id)
    local newYearFundComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NewYearFundComponent)
    local t =  CfUtils.GetCf(AutoIds.IdSetting6711, "NewYearFundRewardVo", true)

    for k, v in pairs(t) do
        if checkNumber(v.group) == checkNumber(id) then
            local isCanDraw = NewYearFundUtils.IsCanDrawRewardBuyDay(v.group, v.taskNum)
            if isCanDraw then
                return true
            end
        end
    end
    return false
end

function NewYearFundUtils.GetOneKeyDrawRewardIds(id)
    local t =  CfUtils.GetCf(AutoIds.IdSetting6711, "NewYearFundRewardVo", true)

    local str = ""
    for k, v in pairs(t) do
        if checkNumber(v.group) == checkNumber(id) then
            local isCanDraw, ids = NewYearFundUtils.IsCanDrawRewardBuyDay(v.group, v.taskNum)
            if isCanDraw then
                if str == "" then
                    str = ids
                else
                    str = str..","..ids
                end
            end
        end
    end
    return str
end

function NewYearFundUtils.IsCanDrawBox()
    local newYearFundComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NewYearFundComponent)
    return (newYearFundComponent._isPay == 1)
end

return NewYearFundUtils
